import{z as l,x as n,o as E,c as D,q as t,j as B,D as e,d as o,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"轨道缺陷来源","description":"","frontmatter":{"title":"轨道缺陷来源","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/track-defect-sources.md","filePath":"litho/track-defect-sources.md","lastUpdated":1791063341000}'),d={name:"litho/track-defect-sources.md"};function A(p,a,c,h,_,m){const r=n("Mermaid");return E(),D("div",null,[a[2]||(a[2]=t('<h1 id="轨道缺陷来源" tabindex="-1">轨道缺陷来源 <a class="header-anchor" href="#轨道缺陷来源" aria-label="Permalink to &quot;轨道缺陷来源&quot;">​</a></h1><div class="epigraph"><p>扫描仪写潜像；轨道贡献颗粒、条纹、溅射和升华。缺陷检测要先问在哪一段机台。</p><footer>—— 对照 track defect 分类：涂胶条纹、显影溅射、热板升华、传送刮伤</footer></div><p><a href="/litho/hotplate-uniformity">上一课</a>是热。缺口是颗粒与图案缺陷的<strong>轨道源</strong>，与 <a href="/litho/immersion-defects">浸没缺陷</a>、掩模缺陷分开记账。本课分类，不写检测算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/patterning-inspection-tools">图形化检测</a> 看见缺陷，不一定是曝光。涂胶条纹、气泡、 splatter、热板升华再沉积、机械手刮边、显影液干斑，都在 track。分错源会去调剂量或换掩模。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按模块分账：涂胶杯（条纹、彗尾、 splatter）、热板（颗粒、升华）、显影碗（溅射、水印）、传送（刮伤、掉片边缘渣）。抽检：涂胶后、曝光前、显影后分步检测，才能定位。换胶与换杯清洗周期是缺陷率的一等参数。</p>',7)),(E(),B(i,null,{default:e(()=>[s(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20COAT%5B%22%E6%B6%82%E8%83%B6%E6%9D%AF%22%5D%20--%3E%20D1%5B%22%E6%9D%A1%E7%BA%B9%20%2F%20%E6%B0%94%E6%B3%A1%22%5D%0A%20%20HP%5B%22%E7%83%AD%E6%9D%BF%22%5D%20--%3E%20D2%5B%22%E5%8D%87%E5%8D%8E%E5%86%8D%E6%B2%89%E7%A7%AF%22%5D%0A%20%20DEV%5B%22%E6%98%BE%E5%BD%B1%22%5D%20--%3E%20D3%5B%22%E6%BA%85%E5%B0%84%20%2F%20%E6%B0%B4%E5%8D%B0%22%5D%0A%20%20ROB%5B%22%E4%BC%A0%E9%80%81%22%5D%20--%3E%20D4%5B%22%E5%88%AE%E4%BC%A4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">胺污染是化学缺陷：CD 漂、不明欠曝。它走空气，不像颗粒走 SEM。监控要用化学传感器，不只缺陷机。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><span class="marginnote">卫星点可以类比甩干机甩水：旋涂把多余胶液甩出杯壁，高速气流再把液丝撕成小滴，回落的每一滴烘干后就是一颗点状缺陷——所以它偏向旋转下游方位，大小也和液滴谱一致。</span></p><p>液滴在旋涂中被气流撕碎成卫星点；升华物在较冷盖上凝结再掉。显影溅射把未溶胶块打到邻区。机制不同，清洗配方不同。</p><p><span class="marginnote">升华再沉积翻译成大白话：胶里的某些成分没等到烘干就直接变成气体飘走，撞上较冷的盖板又凝回固体，之后掉回晶圆成为颗粒。它与机械颗粒的区别在于「是工艺自己长出来的」，清洗盖板周期比换滤芯更对症。</span></p>',5)),(E(),B(i,null,{default:e(()=>[s(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E6%97%8B%E6%B6%82%E6%B6%B2%E6%BB%B4%22%5D%20--%3E%20TEAR%5B%22%E9%AB%98%E9%80%9F%E6%B0%94%E6%B5%81%E6%92%95%E7%A2%8E%22%5D%0A%20%20TEAR%20--%3E%20SAT%5B%22%E5%8D%AB%E6%98%9F%E7%82%B9%E8%90%BD%E5%9B%9E%E7%89%87%E4%B8%8A%22%5D%0A%20%20HOT%5B%22%E7%83%AD%E6%9D%BF%E5%8D%87%E6%B8%A9%22%5D%20--%3E%20SUB%5B%22%E6%88%90%E5%88%86%E5%8D%87%E5%8D%8E%E6%88%90%E6%B0%94%E4%BD%93%22%5D%0A%20%20SUB%20--%3E%20COND%5B%22%E8%BE%83%E5%86%B7%E8%A1%A8%E9%9D%A2%E5%87%9D%E7%BB%93%22%5D%0A%20%20COND%20--%3E%20REDEP%5B%22%E5%86%8D%E6%B2%89%E7%A7%AF%E6%88%90%E9%A2%97%E7%B2%92%22%5D%0A%20%20DEV%5B%22%E6%98%BE%E5%BD%B1%E5%96%B7%E6%B7%8B%22%5D%20--%3E%20SPL%5B%22%E6%BA%85%E8%B5%B7%E6%9C%AA%E6%BA%B6%E8%83%B6%E5%9D%97%22%5D%0A%20%20SPL%20--%3E%20NEI%5B%22%E8%90%BD%E5%88%B0%E9%82%BB%E8%BF%91%E5%9B%BE%E5%BD%A2%E5%8C%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课边缘曝光：有意用光清边，不是缺陷，但过曝会伤边缘器件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轨道缺陷按模块分账，分步检测定位。</li><li>不要默认缺陷来自扫描仪或掩模。</li><li>出处：track defect 工艺通识；检测课。</li></ul><p><span class="marginnote">常见误区：看见缺陷就调剂量或换掩模。轨道缺陷不随剂量变，也不跟着图形版图走——用分步检测看它在涂胶后、曝光前还是显影后冒出来，是定位源头的省时做法。</span></p>',5))])}const T=l(d,[["render",A]]);export{u as __pageData,T as default};
